export function normalizeText(str) {
  return (str || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .trim();
}

export function getAlbumsList(categoryId = 'GERAL') {
  const cat = ALBUMS_BY_CATEGORY[categoryId] || ALBUMS_BY_CATEGORY.GERAL;
  return Object.values(cat);
}

/**
 * Busca com correspondencia estrita e exclusiva em 'titulo' e 'artista'.
 * Ignora completamente ano e genero ao digitar.
 */
export function searchAlbumsByCategory(query, categoryId = 'GERAL', limit = 6) {
  const normQuery = normalizeText(query);
  if (!normQuery || normQuery.length < 1) return [];

  const list = getAlbumsList(categoryId);
  const queryWords = normQuery.split(' ').filter(Boolean);

  const scored = list.map(album => {
    const titleNorm = normalizeText(album.titulo);
    const artistNorm = normalizeText(album.artista);
    const combinedNorm = `${titleNorm} ${artistNorm}`;

    // Somente titulo e artista
    const matchesAllWords = queryWords.every(w => combinedNorm.includes(w));
    if (!matchesAllWords) return null;

    let score = 0;
    if (titleNorm === normQuery) score += 1000;
    else if (titleNorm.startsWith(normQuery)) score += 500;
    else if (artistNorm.startsWith(normQuery)) score += 400;
    else if (titleNorm.includes(normQuery)) score += 250;
    else if (artistNorm.includes(normQuery)) score += 200;
    else score += 100;

    return { album, score };
  }).filter(Boolean);

  return scored
    .sort((a, b) => b.score - a.score)
    .slice(0, limit)
    .map(item => item.album);
}

export const START_DATE = new Date('2025-01-01T00:00:00-03:00');

export function getBrasiliaDate(date = new Date()) {
  const formatter = new Intl.DateTimeFormat('en-CA', {
    timeZone: 'America/Sao_Paulo',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit'
  });
  const [year, month, day] = formatter.format(date).split('-').map(Number);
  return new Date(year, month - 1, day, 0, 0, 0, 0);
}

export function calculateDayNumber(date = new Date()) {
  const bDate = getBrasiliaDate(date);
  const bStart = getBrasiliaDate(START_DATE);
  const diffTime = bDate.getTime() - bStart.getTime();
  const diffDays = Math.floor(diffTime / (1000 * 60 * 60 * 24));
  return Math.max(1, diffDays + 1);
}

export function formatDateKey(date = new Date()) {
  const bDate = getBrasiliaDate(date);
  const y = bDate.getFullYear();
  const m = String(bDate.getMonth() + 1).padStart(2, '0');
  const d = String(bDate.getDate()).padStart(2, '0');
  return `${y}-${m}-${d}`;
}

export function getDailyTargetAlbum(categoryId = 'GERAL', date = new Date()) {
  const list = getAlbumsList(categoryId);
  if (!list.length) return null;

  const dateKey = formatDateKey(date);
  const seedString = `${categoryId}_${dateKey}`;
  let hash = 0;
  for (let i = 0; i < seedString.length; i++) {
    hash = ((hash << 5) - hash) + seedString.charCodeAt(i);
    hash |= 0;
  }
  const index = Math.abs(hash) % list.length;
  const album = list[index];
  const dayNumber = calculateDayNumber(date);

  return { album, dateKey, dayNumber };
}
